  let LANG='en';
  const MESES_ABREV={
    pt:['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'],
    en:['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],
    es:['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic']
  };
  const MESES_COMPLETOS={
    pt:['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'],
    en:['January','February','March','April','May','June','July','August','September','October','November','December'],
    es:['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']
  };
  /* mesAbrev(i) / mesCompleto(i) — i é 0-based (0=Jan). Devolvem o nome do mês na língua atual. */
  function mesAbrev(i){ return (MESES_ABREV[LANG]||MESES_ABREV.pt)[i]; }
  function mesCompleto(i){ return (MESES_COMPLETOS[LANG]||MESES_COMPLETOS.pt)[i]; }
  const JS_LOCALES={pt:'pt-BR', en:'en-US', es:'es-ES'};
  function jsLocale(){ return JS_LOCALES[LANG]||'pt-BR'; }
  const I18N_LANGS=['pt','en','es'];

  /* Validação ao arrancar: reporta no console qualquer chave incompleta.
     Isto substitui a verificação manual que antes tinha de ser feita por fora —
     agora é o próprio sistema que se garante. */
